using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputSetupBoundsProof {
 static int W(byte[] b,int at){return BitConverter.ToInt16(b,at);}
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),compact=File.ReadAllBytes(a[1]),expected=File.ReadAllBytes(a[2]);var state=new InputSetupState{Staff=W(ds,0x83e0),LeftEnd=W(ds,0x83e2),RightEnd=W(ds,0x83ea),Size=BitConverter.ToSingle(ds,0x83e6),LeftPosition=W(ds,0x8530),RightPosition=W(ds,0x8532),MeterTop=W(ds,0x852c),MeterBottom=W(ds,0x852e)};var rows=new List<float[]>();int at=0;for(int i=0;i<W(ds,0x80d2);i++){int n=(int)BitConverter.ToSingle(compact,at);var row=new float[n];Buffer.BlockCopy(compact,at+4,row,0,n*4);rows.Add(row);at+=(n+1)*4;}var result=InputSetupBounds.Find(rows,state);if(result.Left!=W(expected,0x8530)||result.Right!=W(expected,0x8532)||result.MeterTop!=W(expected,0x852c)||result.MeterBottom!=W(expected,0x852e))throw new Exception("Setup bounds/metre mismatch: "+result.Left+", "+result.Right);Console.WriteLine("PASS original setup bounds "+result.Left+".."+result.Right+" and metre for "+rows.Count+" compact items");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
